using System.Collections.ObjectModel;using System.Windows.Input;using OdinVault.Manager.Wpf.Infrastructure;using OdinVault.Manager.Wpf.Services;namespace OdinVault.Manager.Wpf.ViewModels;internal sealed class StorageViewModel:ObservableObject{readonly AgentDashboardClient c;bool loading,testing;string? error,testStatus;string local="—",free="—";StorageRow? selected;public ObservableCollection<StorageRow> Targets{get;}=[];public bool IsLoading{get=>loading;private set=>Set(ref loading,value);}public bool IsTesting{get=>testing;private set=>Set(ref testing,value);}public string? Error{get=>error;private set=>Set(ref error,value);}public string? TestStatus{get=>testStatus;private set=>Set(ref testStatus,value);}public string Local{get=>local;private set=>Set(ref local,value);}public string Free{get=>free;private set=>Set(ref free,value);}public StorageRow? Selected{get=>selected;set=>Set(ref selected,value);}public ICommand TestCommand{get;}public StorageViewModel(AgentDashboardClient c){this.c=c;TestCommand=new AsyncCommand(TestAsync);}public async Task LoadAsync(){IsLoading=true;Error=null;try{var x=await c.StorageAsync();if(x is null)return;Local=x.Local.Directory;Free=Size(x.Local.FreeBytes);Targets.Clear();foreach(var t in x.Targets)Targets.Add(new(t.Id,t.Name,t.Type==1?"Google Drive":"Replica",t.IsEnabled?"فعال":"غیرفعال",t.IsConnected?"متصل":"قطع",t.LinkedDatabases,t.SucceededReplicas,t.FailedReplicas,PersianDateFormatter.Format(t.LastActivityAtUtc),t.LastError));}catch(Exception e){Error=e.Message;}finally{IsLoading=false;}}async Task TestAsync(){if(Selected is null)return;IsTesting=true;TestStatus="در حال تست اتصال…";try{var r=await c.TestStorageAsync(Selected.Id);TestStatus=r?.Success==true?(string.IsNullOrWhiteSpace(r.Message)?"اتصال موفق بود.":r.Message):$"اتصال ناموفق بود: {r?.Message}";await LoadAsync();}catch(Exception e){TestStatus=$"خطا: {e.Message}";}finally{IsTesting=false;}}static string Size(long? v){if(v is null)return"—";double n=v.Value;string[]u=["B","KB","MB","GB","TB"];int i=0;while(n>=1024&&i<4){n/=1024;i++;}return$"{n:0.#} {u[i]}";}}internal sealed record StorageRow(Guid Id,string Name,string Type,string State,string Connection,int Databases,int Success,int Failed,string Activity,string? Error);